WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT b.id, b.peca, b.geracao, b.file_id, b.url, b.cor, b.aplicada, b.conferida_get, COALESCE(b.previa_base64, (SELECT string_agg(a.conteudo_base64, '' ORDER BY a.parte) FROM pedido_arquivos a WHERE a.pedido_id = b.pedido_id AND a.tipo = 'previa:' || b.peca || ':' || b.geracao)) AS previa_base64 FROM pecas_banner b JOIN pedidos p ON p.pedido_id = b.pedido_id JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) WHERE b.pedido_id = :pedido_id ORDER BY b.geracao DESC, b.peca LIMIT 40
